mapper.select:
SELECT occurrence.exception_occurrence_id AS exceptionOccurrenceId, occurrence.exception_case_id AS exceptionCaseId, occurrence.validation_run_id AS validationRunId, vr.run_no AS runNo, vr.validation_month AS validationMonth, occurrence.exception_type AS exceptionType, occurrence.reason_code AS reasonCode, occurrence.source_entity_type AS sourceEntityType, occurrence.source_entity_id AS sourceEntityId, occurrence.evidence_snapshot::text AS evidenceJson, occurrence.is_new_case AS newCase, occurrence.was_reopened AS reopened, occurrence.detected_at AS detectedAt FROM fgc.exception_occurrence occurrence JOIN fgc.validation_run vr ON vr.validation_run_id = occurrence.validation_run_id WHERE occurrence.exception_case_id IN
#{id}
ORDER BY occurrence.exception_case_id, occurrence.detected_at DESC, occurrence.exception_occurrence_id DESC

SELECT ea.exception_action_id AS exceptionActionId, ea.exception_case_id AS exceptionCaseId, ea.action_seq AS actionSeq, ea.from_status AS fromStatus, ea.to_status AS toStatus, ea.action_type AS actionType, ea.reason, ea.evidence_ref AS evidenceRef, ea.action_by AS actionBy, actor.login_id AS actionByLoginId, ea.action_at AS actionAt FROM fgc.exception_action ea JOIN fgc.app_user actor ON actor.user_id = ea.action_by WHERE ea.exception_case_id IN
#{id}
ORDER BY ea.exception_case_id, ea.action_seq
